import {announcementText} from './scenario-announcements.js?v=scenario-start-preview-1';
const targets=['briefing','winMessage','lossMessage'];
const actionTargets=a=>a.type==='dialogText'?['briefing']:a.outcome==='won'?['winMessage']:a.outcome==='lost'?['lossMessage']:['winMessage','lossMessage'];
const forbidden=/[\x00-\x08\x0b\x0c\x0e-\x1f]/;
export function validateDialogText(value){if(typeof value!=='string'||!value.trim()||value.length>1500||forbidden.test(value))throw Error('Scenario dialog text needs 1–1,500 characters of plain text.');return value.trim();}
export function validateTextOverrides(value,sources=null){if(value===undefined)value={};if(!value||Array.isArray(value)||typeof value!=='object'||Object.keys(value).some(k=>!targets.includes(k)))throw Error('Invalid scenario text overrides.');const out={};for(const key of targets)if(Object.hasOwn(value,key)){const text=value[key];if(typeof text!=='string'||text.length>4000||forbidden.test(text))throw Error('Invalid saved scenario dialog text.');out[key]=text;}if(sources){const required=new Set(sources.filter(({e,state})=>['dialogText','resultText'].includes(e.type)&&state.status==='triggered').flatMap(({e})=>actionTargets(e)));if(required.size!==Object.keys(out).length||[...required].some(key=>!Object.hasOwn(out,key)))throw Error('Saved dialog text does not match executed scenario actions.');}return out;}
export function setScenarioDialogText(c,action){const message=announcementText(action.message,c).replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g,''),keys=actionTargets(action);c.scenario.textOverrides??={};for(const key of keys)c.scenario.textOverrides[key]=message;return{ok:true,message};}
export const dialogTextTarget=action=>action.type==='dialogText'?'Current instructions':action.outcome==='won'?'Victory message':action.outcome==='lost'?'Loss message':'Victory and loss messages';
